"use client"

import { useState } from "react"
import { Navbar } from "@/components/Navbar"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import Link from "next/link"

export default function CoursesPage() {
  const [searchQuery, setSearchQuery] = useState("")
  const [sortBy, setSortBy] = useState("popular")

  const courses = [
    {
      id: 1,
      title: "Web Development Fundamentals",
      description: "Learn the basics of web development with HTML, CSS, and JavaScript",
      instructor: "John Doe",
      rating: 4.8,
      students: 1234,
      price: 49.99,
      category: "Programming",
      level: "Beginner",
      image: "https://images.pexels.com/photos/1181671/pexels-photo-1181671.jpeg"
    },
    {
      id: 2,
      title: "Data Science Essentials",
      description: "Master the fundamentals of data science and analytics",
      instructor: "Jane Smith",
      rating: 4.9,
      students: 856,
      price: 59.99,
      category: "Data Science",
      level: "Intermediate",
      image: "https://images.pexels.com/photos/7688336/pexels-photo-7688336.jpeg"
    },
    {
      id: 3,
      title: "Digital Marketing Masterclass",
      description: "Complete guide to modern digital marketing strategies",
      instructor: "Mike Johnson",
      rating: 4.7,
      students: 2341,
      price: 39.99,
      category: "Marketing",
      level: "All Levels",
      image: "https://images.pexels.com/photos/905163/pexels-photo-905163.jpeg"
    },
    {
      id: 4,
      title: "Mobile App Development with React Native",
      description: "Build cross-platform mobile apps with React Native",
      instructor: "Sarah Wilson",
      rating: 4.6,
      students: 1567,
      price: 54.99,
      category: "Programming",
      level: "Intermediate",
      image: "https://images.pexels.com/photos/1181244/pexels-photo-1181244.jpeg"
    },
    {
      id: 5,
      title: "Business Analytics and Intelligence",
      description: "Learn to make data-driven business decisions",
      instructor: "Robert Brown",
      rating: 4.8,
      students: 987,
      price: 64.99,
      category: "Business",
      level: "Advanced",
      image: "https://images.pexels.com/photos/7681091/pexels-photo-7681091.jpeg"
    },
    {
      id: 6,
      title: "UI/UX Design Principles",
      description: "Master modern user interface and experience design",
      instructor: "Emily Chen",
      rating: 4.9,
      students: 1432,
      price: 49.99,
      category: "Design",
      level: "Beginner",
      image: "https://images.pexels.com/photos/196644/pexels-photo-196644.jpeg"
    },
  ]

  const filteredCourses = courses.filter(course =>
    course.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    course.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
    course.instructor.toLowerCase().includes(searchQuery.toLowerCase())
  )

  const sortedCourses = [...filteredCourses].sort((a, b) => {
    switch (sortBy) {
      case "popular":
        return b.students - a.students
      case "rating":
        return b.rating - a.rating
      case "priceAsc":
        return a.price - b.price
      case "priceDesc":
        return b.price - a.price
      default:
        return 0
    }
  })

  return (
    <>
      <Navbar />
      <div className="min-h-screen bg-gray-50 pt-20">
        <div className="container mx-auto px-4 py-8">
          {/* Search and Filter Section */}
          <div className="mb-8 bg-white p-6 rounded-lg shadow-sm">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              <div className="col-span-full lg:col-span-2">
                <Input
                  placeholder="Search courses..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full"
                />
              </div>
              <div>
                <Select value={sortBy} onValueChange={setSortBy}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sort by" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="popular">Most Popular</SelectItem>
                    <SelectItem value="rating">Highest Rated</SelectItem>
                    <SelectItem value="priceAsc">Price: Low to High</SelectItem>
                    <SelectItem value="priceDesc">Price: High to Low</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          {/* Courses Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {sortedCourses.map((course) => (
              <Card key={course.id} className="overflow-hidden hover:shadow-lg transition-shadow">
                <div className="aspect-video relative">
                  <img 
                    src={course.image} 
                    alt={course.title}
                    className="absolute inset-0 w-full h-full object-cover"
                  />
                </div>
                <div className="p-6">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium px-2 py-1 bg-primary/10 text-primary rounded">
                      {course.category}
                    </span>
                    <span className="text-sm text-muted-foreground">
                      {course.level}
                    </span>
                  </div>
                  <h3 className="text-xl font-semibold mb-2">{course.title}</h3>
                  <p className="text-muted-foreground mb-4">{course.description}</p>
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium">Instructor: {course.instructor}</p>
                      <div className="flex items-center mt-1">
                        <span className="text-yellow-400">★</span>
                        <span className="ml-1 text-sm">{course.rating}</span>
                        <span className="mx-2 text-muted-foreground">•</span>
                        <span className="text-sm text-muted-foreground">{course.students} students</span>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-lg font-bold mb-2">${course.price}</p>
                      <Link href={`/courses/${course.id}`}>
                        <Button variant="outline">Learn More</Button>
                      </Link>
                    </div>
                  </div>
                </div>
              </Card>
            ))}
          </div>

          {sortedCourses.length === 0 && (
            <div className="text-center py-12">
              <h3 className="text-xl font-semibold mb-2">No courses found</h3>
              <p className="text-muted-foreground">Try adjusting your search criteria</p>
            </div>
          )}
        </div>
      </div>
    </>
  )
}
